import sr28 from "@/lib/data/sr28.json";
import type { FoodRecord, NutrientKey, Nutrients } from "@/lib/types";

/**
 * USDA National Nutrient Database for Standard Reference, Release 28 (USDA ARS, 2015).
 * FoodData Central republishes this dataset as "SR Legacy"; NDB numbers are searchable there.
 * The bundled copy is generated by scripts/build-foods.mjs from the unmodified ABBREV.txt file.
 */
export const SR28_CITATION =
  "U.S. Department of Agriculture, Agricultural Research Service. USDA National Nutrient Database for Standard Reference, Release 28 (2015). Republished in FoodData Central as SR Legacy.";

export const NUTRIENT_KEYS: NutrientKey[] = [
  "kcal", "protein", "carbs", "fat", "fiber", "sugar", "sodium", "satFat",
  "calcium", "iron", "potassium", "vitC", "vitD", "b12",
];

type Row = [string, string, ...(number | null)[]];
const rows = sr28 as unknown as Row[];

const byNdb = new Map<string, FoodRecord>();
for (const r of rows) {
  const vals = r.slice(2) as (number | null)[];
  const per100g = {} as Nutrients;
  const missing: FoodRecord["missing"] = {};
  NUTRIENT_KEYS.forEach((k, i) => {
    const v = vals[i];
    if (v == null || Number.isNaN(v)) {
      per100g[k] = 0;
      missing[k] = true;
    } else per100g[k] = v;
  });
  byNdb.set(r[0], {
    ndb: r[0],
    description: r[1],
    per100g,
    missing,
    refusePct: (vals[14] as number | null) ?? null,
    source: "usda-sr28",
  });
}

export function getFood(ndb: string): FoodRecord | undefined {
  return byNdb.get(ndb);
}

export function fdcSearchUrl(ndb: string) {
  return `https://fdc.nal.usda.gov/food-search?query=${encodeURIComponent(ndb)}&type=SR%20Legacy`;
}

const ABBREV: [RegExp, string][] = [
  [/\bCKD\b/g, "cooked"], [/\bRSTD\b/g, "roasted"], [/\bBLD\b/g, "boiled"], [/\bDRND\b/g, "drained"],
  [/\bCND\b/g, "canned"], [/\bFRZ\b/g, "frozen"], [/\bUNPREP\b/g, "unprepared"], [/\bPLN\b/g, "plain"],
  [/\bWHL\b/g, "whole"], [/\bLN\b/g, "lean"], [/\bGRD\b/g, "ground"], [/\bW\/\b/g, "with "],
  [/\bWO\/\b/g, "without "], [/\bH2O\b/g, "water"], [/\bLO\b/g, "low"], [/\bNA\b/g, "sodium"],
  [/\bPDR\b/g, "powder"], [/\bPROT\b/g, "protein"], [/\bSOL\b/g, "solids"], [/\bFRSH\b/g, "fresh"],
  [/\bSWT\b/g, "sweet"], [/\bMXD\b/g, "mixed"], [/\bSP\b/g, "species"], [/\bBRST\b/g, "breast"],
  [/\bBNLESS\b/g, "boneless"], [/\bINCL\b/g, "including"], [/\bSKN\b/g, "skin"], [/\bSAU\b/g, "sauce"],
];

export function prettyDescription(desc: string) {
  let s = desc;
  for (const [re, rep] of ABBREV) s = s.replace(re, rep);
  s = s.toLowerCase().replace(/,/g, ", ").replace(/\s+/g, " ").trim();
  return s.charAt(0).toUpperCase() + s.slice(1);
}

/** Simple ranked keyword search over all 8,789 SR28 foods. */
export function searchFoods(query: string, limit = 20): FoodRecord[] {
  const terms = query.toLowerCase().split(/[\s,]+/).filter(Boolean);
  if (!terms.length) return [];
  const scored: { f: FoodRecord; s: number }[] = [];
  for (const f of byNdb.values()) {
    const d = prettyDescription(f.description).toLowerCase();
    let s = 0;
    let all = true;
    for (const t of terms) {
      const idx = d.indexOf(t);
      if (idx === -1) { all = false; break; }
      s += idx === 0 ? 6 : d.includes(" " + t) || d.includes("," + t) ? 3 : 1;
    }
    if (!all) continue;
    if (/\braw\b/.test(d)) s += 1;
    s -= d.length / 80; // prefer shorter, more generic entries
    scored.push({ f, s });
  }
  return scored.sort((a, b) => b.s - a.s).slice(0, limit).map((x) => x.f);
}
